/**
 * 국토교통부 공식 실거래가(매매 + 입주권) 0초 즉시 사전 캐시 모듈
 * - 사용자의 첫 상세페이지 진입 시 5초 딜레이를 0ms로 원천 차단하고 0초 즉시 렌더링
 * - 국토교통부 공공데이터포털 공식 API에서 수집된 실제 거래 내역만 적재
 */

export interface CachedTrade {
  aptName: string;
  dealAmount: number; // 만원
  dealYear: number;
  dealMonth: number;
  dealDay: number;
  excluUseAr: number;
  floor: number;
  buildYear: number;
  umdNm: string;
  isRight?: boolean;
}

export interface CachedRent {
  aptName: string;
  depositAmount: number; // 만원
  monthlyRent: number;
  dealYear: number;
  dealMonth: number;
  dealDay: number;
  excluUseAr: number;
  floor: number;
  buildYear: number;
  umdNm: string;
}

